-- Placement pool expansion: copies well-leveled, already-reviewed content from
-- pool=practice as fresh independent rows into pool=placement, across all 6
-- CEFR levels, for all 9 adaptive-placement item types. Fixes the root cause of
-- the user-reported repetition: pickAdaptiveItem (backend/src/placement/routes.ts)
-- defaulted null cefr_level to START_LEVEL distance=0, so the 40 original
-- placement items (all null cefr_level) always won the tie-break. This seed also
-- backfills cefr_level on those original 40 rows. Idempotent: ON CONFLICT (id) DO
-- NOTHING on inserts; UPDATEs are naturally idempotent.
BEGIN;
UPDATE items SET cefr_level='A2' WHERE pool='placement' AND difficulty='0.25' AND cefr_level IS NULL;
UPDATE items SET cefr_level='B1' WHERE pool='placement' AND difficulty='0.5' AND cefr_level IS NULL;
UPDATE items SET cefr_level='C1' WHERE pool='placement' AND difficulty='0.8' AND cefr_level IS NULL;
COMMIT;
